def is_palindrome(num):
    """Check if a number is a palindrome."""
    return str(num) == str(num)[::-1]


def even_odd_palindrome(n):
    """Return the number of even and odd integer palindromes within the range (1, n)."""
    assert 1 <= n <= 10**3, "Invalid input: n should be between 1 and 10^3"

    num_even = 0
    num_odd = 0

    for i in range(1, n+1):
        if is_palindrome(i):
            if i % 2 == 0:
                num_even += 1
            else:
                num_odd += 1

    return (num_even, num_odd)
```

